import { publishedCampaigns, campaignBookURL, campaignSummary, campaignVictorySummary } from './published-campaigns.js';
import { reviewedBoards, sourceLandmarkName } from './official-maps.js';
import { mapEvidence } from './map-data.js';
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const action = (a) => `data-action="${esc(JSON.stringify(a))}"`;
export function openingPanel(s, actions, selectedDefinition, selectedHex) {
    const opening = s.opening, rules = s.scenario.sourceCampaign, k = s.kingdoms.find(k => k.id === s.currentKingdom);
    const available = actions.filter(a => a.type.startsWith('opening-'));
    const choices = available.filter(a => a.type === 'opening-choice');
    if (choices.length) {
        const source = rules.preChoices?.find(c => c.id === choices[0].choiceId);
        return `<div class="guide"><strong>Resolve a source inconsistency</strong>${esc(source.label)}</div><form class="opening-form"><label for="opening-choice">Printed-book / table ruling</label><select id="opening-choice" name="action">${choices.map(a => `<option value="${esc(JSON.stringify(a))}">${esc(source.options.find(o => o.value === a.value)?.label)}</option>`).join('')}</select><button class="primary-button" type="submit">Record ruling & continue</button></form><p class="small-note">Your choice is recorded in the campaign log and backup. The review copy is inconsistent; this is an explicit table ruling. Printed opening incomes are retained; reconcile disputed incomes with your corrected book using Full tabletop controls.</p>`;
    }
    const switches = available.filter(a => a.type === 'opening-switch');
    const exchanges = available.filter(a => a.type === 'opening-exchange-coven');
    const controls = available.filter(a => a.type === 'opening-control');
    const covens = available.filter(a => a.type === 'opening-coven');
    const builds = available.filter(a => a.type === 'opening-build' || a.type === 'opening-hero');
    const definitions = [...new Set(builds.map(a => a.defId))].map(id => s.unitDefinitions.find(d => d.id === id));
    const selection = definitions.find(d => d.id === selectedDefinition) ?? definitions.find(d => opening.remainingHeroes.includes(d.id)) ?? definitions.find(d => opening.remainingFreeUnits.some(u => u.defId === d.id && !u.optional)) ?? definitions[0];
    const targets = controls.length ? controls : selection ? builds.filter(a => a.defId === selection.id) : covens;
    const done = available.find(a => a.type === 'opening-done');
    const free = s.opening.remainingFreeUnits.length, heroes = opening.remainingHeroes.length;
    return `${switches.length ? `<div class="guide"><strong>Allied deployment group</strong>These kingdoms may interleave their placements. ${switches.map(a => `<button class="secondary-button" ${action(a)}>Deploy ${esc(s.kingdoms.find(k => k.id === a.kingdom)?.name)}</button>`).join('')}</div>` : ''}<div class="objective"><div class="eyebrow">Campaign opening</div><p>Choose your opening forces and place the required free pieces. Unspent gold stays in your treasury unless this campaign says otherwise.</p></div><div class="setup-tags"><span>${k.gold} gold available</span><span>${heroes} Heroes to place</span><span>${free} free Armies to place</span><span>${opening.remainingCovens} Covens to place</span></div>${controls.length ? '<div class="guide"><strong>Choose starting control</strong>This choice happens before any kingdom recruits. Choose a permitted settlement below.</div>' : `<div class="guide"><strong>${esc(k.name)} deploys</strong>Required free units appear alongside purchasable Armies. Legal arrival hexes follow the printed setup.</div>`}${!controls.length && definitions.length ? `<div class="opening-counters">${definitions.map(d => { const required = opening.remainingFreeUnits.some(u => u.defId === d.id) || opening.remainingHeroes.includes(d.id); return `<button class="${selection?.id === d.id ? 'active' : ''}" data-opening-def="${esc(d.id)}"><strong>${esc(d.name)}</strong><small>${required ? (opening.remainingFreeUnits.some(u => u.defId === d.id && u.optional) ? 'Optional · free' : 'Required · free') : `${d.cost} gold`} · ${d.light} Light / ${d.heavy} Heavy</small></button>`; }).join('')}</div>` : ''}${targets.length ? arrivalForm(s, targets, controls.length ? 'Place Control' : targets[0].type === 'opening-hero' ? 'Place Hero' : targets[0].type === 'opening-build' ? 'Recruit & place' : 'Place Coven', selectedHex) : done ? '<p class="small-note">Opening purchases complete. Finish deployment when you are ready.</p>' : '<p class="small-note">No legal arrival for this counter. Place another required counter or free an arrival hex.</p>'}${!controls.length && covens.length && targets !== covens ? `<details class="opening-covens"><summary>Place required Coven · ${opening.remainingCovens} remaining</summary>${arrivalForm(s, covens, 'Place Coven', selectedHex)}</details>` : ''}${exchanges.length ? `<details><summary>Optional · trade one Control for a Coven</summary>${arrivalForm(s, exchanges, 'Exchange Control', selectedHex)}</details>` : ''}${done ? `<button class="secondary-button full" ${action(done)}>Finish ${esc(k.name)} deployment</button>` : '<p class="small-note">Place every required free Army, Hero and Coven before finishing deployment.</p>' + (heroes && !controls.length && !available.some(a => a.type === 'opening-hero') ? '<div class="guide"><strong>No legal Hero arrival</strong>The rules require an unbesieged arrival. Earlier placements may have blocked every location. Use Campaign to restart and revise the opening deployments.</div>' : '')}`;
}
function arrivalForm(s, actions, title, selectedHex) { return `<form class="opening-form"><label for="opening-arrival-${title.replaceAll(' ', '-')}">${esc(title)} · legal arrival</label><select id="opening-arrival-${title.replaceAll(' ', '-')}" name="action">${actions.map(a => { const id = 'hexId' in a ? a.hexId : 'toHex' in a ? a.toHex : '', h = s.hexes.find(h => h.id === id); return `<option value="${esc(JSON.stringify(a))}" ${id === selectedHex ? 'selected' : ''}>${esc(arrivalName(s, h))} · ${esc(h.terrain)}</option>`; }).join('')}</select><button class="primary-button" type="submit">${esc(title)}</button></form>`; }
function arrivalName(s, h) { if (h.settlement)
    return h.settlement.name; if (sourceLandmarkName(h.id))
    return sourceLandmarkName(h.id); const nearby = s.hexes.filter(t => t.settlement).map(t => ({ t, d: Math.max(Math.abs(h.q - t.q), Math.abs(h.r - t.r), Math.abs(h.q + h.r - t.q - t.r)) })).sort((a, b) => a.d - b.d)[0]; return `${h.mine ? 'Mine' : h.terrain === 'lair' ? 'Lair' : `Hex ${h.q}, ${h.r}`}${nearby ? ` · ${nearby.d} from ${nearby.t.settlement.name}` : ''}`; }
export function campaignEventPanel(s, actions, selectedHex) { const choices = actions.filter(a => a.type === 'campaign-abandon' || a.type === 'campaign-displace'); const abandon = choices[0]?.type === 'campaign-abandon'; return `<div class="guide"><strong>${abandon ? 'Drums in the Deep · Abandoned Lair' : 'Osterlich arrives at the Spire'}</strong>${abandon ? 'Choose one eligible Lair for your alliance. A Lair containing a controlled Monster cannot be abandoned.' : 'Choose an adjacent legal hex for the displaced unit. The existing war position is preserved.'}</div>${arrivalForm(s, choices, abandon ? 'Abandon Lair' : 'Move displaced unit', selectedHex)}`; }
export function campaignReference() { return `<p>The full book contributes the introduction, 17 Scrolls campaigns, ten Chronicle starts, and linked Chronicle play. Setups, postures and objectives are source facts; a few inconsistencies in the review copy require a recorded table ruling.</p><p><a href="${campaignBookURL}" target="_blank" rel="noopener">Official publisher · complete Campaign Book gallery ↗</a></p><div class="codex-grid">${publishedCampaigns.map(s => `<article class="codex-entry" data-search="${esc(JSON.stringify(s).toLowerCase())}"><small>${esc(s.series)} · source pp. ${s.pages.join(', ')}</small><h3>${esc(s.name)}</h3><p>${esc(campaignSummary(s))}</p><p>${esc(campaignVictorySummary(s))}</p>${s.sourceConflicts?.length ? `<details><summary>Source qualifications</summary><p>${esc(s.sourceConflicts.join(' '))}</p></details>` : ''}<button class="secondary-button" data-published-campaign="${esc(s.id)}">Choose campaign</button></article>`).join('')}</div>`; }
export function mapReference() { return `<p>All four maps use inspected source terrain and settlement characteristics on one lattice. North/south half hexes combine at the seam; clipped standalone hexes are gated by visible area. Crossings under review are listed below.</p><p><a href="${mapEvidence.source.url}" target="_blank" rel="noopener">VASSAL · board source and module ↗</a></p><p>Board seams: ${mapEvidence.seams.coverage.verifiedSides} of ${mapEvidence.seams.coverage.candidateSides} sides reviewed. ${esc(mapEvidence.seams.uncertainties.map(u => u.reason).join(" "))}</p><div class="codex-grid">${reviewedBoards.map(b => `<article class="codex-entry" data-search="${esc(JSON.stringify(b).toLowerCase())}"><h3>${esc(b.name)}</h3><p>${b.hexes.length} source centers · ${b.hexes.filter(h => h.settlement).length} settlements · ${b.edges.length} explicit crossings</p><p>Terrain: ${b.complete.terrain ? 'reviewed' : 'partial'} · Settlements: ${b.complete.settlements ? 'reviewed' : 'partial'} · Crossings: ${b.complete.edges ? 'reviewed' : 'partial'}</p>${b.uncertainties.length ? `<details><summary>${b.uncertainties.length} review qualifications</summary><ul>${b.uncertainties.map((u) => `<li>${esc(u.reason ?? u.note ?? JSON.stringify(u))}</li>`).join('')}</ul></details>` : '<p>Every reviewed item has a source witness.</p>'}</article>`).join('')}</div>`; }
export function campaignBoardTitle(s) { const id = s.scenario.id.replace(/^published-/, ''); const c = publishedCampaigns.find(c => c.id === id); return c ? c.maps.join(' · ') : s.tabletop ? 'Custom campaign table' : 'The Wildlands'; }
